class BankAccount:
    def __init__(self, balance=0):
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("잔액 부족")
        self.balance -= amount


def run(ops):
    acc = BankAccount()
    for kind, amount in ops:
        if kind == "in":
            acc.deposit(amount)
        else:
            acc.withdraw(amount)
    return acc.balance

